import 'dart:io';

import 'package:runfiles/runfiles.dart';

/// Reads an isolated hub spoke's `pubspec.yaml` from runfiles.
///
/// `tool_deps` is a separate, isolated resolution: its spoke is generated by
/// its own `pub.from_lock()` and ships its runtime files like any other.
void main() {
  final runfiles = Runfiles.create();
  final path = runfiles.rlocation(
    'ai_rules_dart++pub+tool_deps__analyzer/pubspec.yaml',
  );
  final pubspec = File(path);
  if (!pubspec.existsSync()) {
    stderr.writeln('The isolated spoke pubspec.yaml is not in runfiles: $path');
    exit(1);
  }
  final content = pubspec.readAsStringSync();
  if (!content.contains('name: analyzer')) {
    stderr.writeln('Unexpected pubspec content at $path:\n$content');
    exit(1);
  }
}
